struct stringx
{
  int refs;
  char *data;
  int length;
};

static bool string_less(const stringx &a, const stringx &b)
{
  int n = a.length < b.length ? a.length : b.length;
  for (int i = 0; i < n; ++i)
  {
    if (a.data[i] < b.data[i])
      return true;
    if (b.data[i] < a.data[i])
      return false;
  }
  return a.length < b.length;
}

struct ref_t
{
  stringx label;
  void *ptr;
  unsigned count;
};

